end

function UIFishPoolGoFishingNode1:Start()
    SetButtonAction(self.BtnRank, Bind(self, self.OnBtnRank))
    SetButtonAction(self.BtnScoreReward, Bind(self, self.OnBtnScoreReward))
    SetButtonAction(self.BtnGoods, Bind(self, self.OnBtnGoods))
    SetButtonAction(self.BtnExchange, Bind(self, self.OnBtnExchange))
end

function UIFishPoolGoFishingNode1:Refresh(fishingPlaceId, parLua)
    self._parLua = parLua

    self._curFishingPlaceId = checkNumber(fishingPlaceId)
    if checkNumber(self._curFishingPlaceId) <= 0 then
        return
    end
    self._activityData = FishingUtils.GetFishPlaceDojoActivityData(self._curFishingPlaceId)
    if not self._activityData then
        return
    end
    self._activityId = checkNumber(self._activityData.contentId)

    self:FillSelf()
end

function UIFishPoolGoFishingNode1:FillSelf()
    CfUtils.FillText(self.TextScoreNumber, self._activityData.score)

    if checkNumber(self._activityData.receivedTicket) == 0 then
        CfUtils.SetActive(self.ActivityPopGroup, true)
        self:FillActiveNode(self._activityData)
    end

    local vo = FishingUtils.GetFishActivityPlanVo(self._activityId)

    CfUtils.FillImage(self.ImgGoods, GoodsConfMgr:GetInstance():GetPhotoPathById(vo.properties)) 
    CfUtils.FillText(self.TextIntegralNumber, GoodsUtils.GetThingNo(vo.properties))

    local go = GameUtils.GetRedPointGo(self.BtnScoreReward)
    if go then
        CfUtils.SetActive(go, FishingUtils.IsHaveCanDrawIntegralReward(self._curFishingPlaceId))
    end
end

--第一次进入活动
function UIFishPoolGoFishingNode1:FillActiveNode(data)
    if not data then
        return
    end

    CfUtils.FillText(self.TextTime, CfUtils.GetTimeHMS(data.remainTime))

    local currencyId = FishingUtils.GetActivityCurrencyId(data.contentId)

    local vo = FishingUtils.GetFishActivityPlanVo(data.contentId)
    if vo then
        CfUtils.FillText(self.ActivityPopGroup.transform:Find("Root/Container/ContentGroup/ScrollView/Viewport/TextDesc"), string.gsub(vo.desc, "\\n", "\n"))
        local rewards = checkTable(RewardConfMgr:GetInstance():_GetRewardData(CfUtils.Split(vo.reward), CfUtils.Split(vo.rewardNum)))
        local data = rewards[1]
        if data then
            CfUtils.FillImage(self.ImgGoods2, GoodsConfMgr:GetInstance():GetPhotoPathById(data.goodsId)) 
            CfUtils.FillText(self.TextGoodsNumber, data.num)
        end
    end

    SetButtonAction(self.BtnConfirm, function()
        fishingComponent:FishingReceiveTicketReq(self._curFishingPlaceId, function()
            CfUtils.SetActive(self.ActivityPopGroup, false)
            UINavigationBarRoot.Instance:SetActive(true)

            self:OnBtnExchange(1)

            local currencyVo = FishingUtils.GetFishActivityPlanVo(self._activityId)
            CfUtils.FillText(self.TextIntegralNumber, GoodsUtils.GetThingNo(currencyVo.properties))
        end, function()
            CfUtils.SetActive(self.ActivityPopGroup, false)
            UINavigationBarRoot.Instance:SetActive(true)
        end)
    end)
end

--排行榜
function UIFishPoolGoFishingNode1:OnBtnRank()
    if FishingUtils.IsAutoing() then
        return
    end

    --进来的时候是否有活动
    if checkNumber(self._activityId) > 0 then
        --判断是否开启中
        local isOpen = FishingUtils.IsActivityOpen(self._curFishingPlaceId)
        if not isOpen then
            GameUtils.Toast(localize("活动已结束"))
            return
        end
    end

    self._parLua._isNotClearScene = true
    UIModule.OpenDialog({ id = Constants.UITypeIds.UIFishpoolActivityRankDialog, parameters = {fishPlaceId = self._curFishingPlaceId}}, {
        {id = Constants.UITypeIds.UIFishPoolGoFishingDialog}
    })
end

